sys_variable_value.value:
(function execute(inputs, outputs) {

var feedbackData = FeedbackUtils.getFeedbackDetails(inputs.feedbackSysId);

    if (feedbackData) {
        outputs.rating = feedbackData.rating;
        outputs.comments = feedbackData.comments;
        outputs.attendee = feedbackData.attendee;
    }


})(inputs, outputs);

